import './session.js';
import { mountCoaching } from './coaching.js';
import { mountProgress } from './progress.js';
const root=document.querySelector('#training-root');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=new Intl.NumberFormat('en-AU',{maximumFractionDigits:2});
const km=value=>Number.isFinite(value)?fmt.format(value/1000):'—';
const sessionDistance=value=>Number.isFinite(value)&&value<1000?`${fmt.format(value)} <small>m</small>`:`${km(value)} <small>km</small>`;
const duration=value=>{if(!Number.isFinite(value))return '—';const n=Math.round(value);return n>=3600?`${Math.floor(n/3600)}h ${Math.floor(n%3600/60)}m`:`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;};
const pace=value=>{if(!Number.isFinite(value))return '—';const n=Math.round(value);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;};
const date=(value,year=false)=>new Date(value+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',...(year?{year:'numeric'}:{})});
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
const logo='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 25 11 7h5L8 25m9 0 8-18h4l-8 18"/></svg>';
let data,lab,windowChoice='90',type='all',busy=false,motion=true,animation,revealObserver;
try{motion=localStorage.getItem('mfa-visual-motion')!=='off';}catch{}
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
async function json(url,options){const response=await fetch(url,options);if(response.status===401){location.replace('/sign-in.html?next='+encodeURIComponent(location.pathname+location.search+location.hash));throw new Error('Sign in to open your record.');}let body;try{body=await response.json();}catch{throw new Error('The service is unavailable. Try again.');}if(!response.ok)throw new Error(body.error||'The request could not finish.');return body;}
function detail(s){return '/app.html?activity='+encodeURIComponent(s.id);}
function line(points,width=600,height=140){if(points.length<2)return '';const xs=points.map(p=>p.t),ys=points.map(p=>p.value),min=Math.min(...ys)-3,max=Math.max(...ys)+3,start=Math.min(...xs),end=Math.max(...xs);return points.map((p,i)=>`${i?'L':'M'}${((p.t-start)/(end-start||1)*width).toFixed(2)},${(height-(p.value-min)/(max-min)*height).toFixed(2)}`).join(' ');}
function latestCard(){const s=data.sessions[0];if(!s)return '<aside class="tr-latest"><span class="tr-eyebrow">Your next chapter</span><h2>Start with a session.</h2><p>Bring your recordings or earlier screenshots into your private record.</p><a class="tr-inline-link" href="/account">Add your history ↗</a></aside>';
 const trace=line(s.sparkline,540),series=s.sparkline.length>1,hrMin=Math.floor(Math.min(...s.sparkline.map(p=>p.value))-3),hrMax=Math.ceil(Math.max(...s.sparkline.map(p=>p.value))+3);
 return `<aside class="tr-latest tr-enter"><div class="tr-latest-top"><span class="tr-eyebrow">Latest session</span><span>${date(s.date)}</span></div><a class="tr-session-title" href="${detail(s)}"><h2>${esc(s.title)}</h2>${arrow}</a><p>${esc(s.source)} · ${esc(s.environment==='indoor'?'Indoor':s.sport)}</p><div class="tr-sensor"><strong>${s.hrBpm===null?duration(s.durationS):Math.round(s.hrBpm)}</strong><span>${s.hrBpm===null?'recorded time':'bpm · average heart rate'}</span></div><div class="tr-heart-trace">${series?`<svg viewBox="0 0 600 165" role="img" aria-label="Recorded heart rate for the latest session"><defs><linearGradient id="hr-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--color-heartRate)" stop-opacity=".22"/><stop offset="1" stop-color="var(--color-heartRate)" stop-opacity="0"/></linearGradient></defs><text class="tr-hr-axis" x="0" y="12">${hrMax}</text><text class="tr-hr-axis" x="0" y="140">${hrMin}</text><g transform="translate(45 0)"><path d="${trace} L540,165 L0,165Z" fill="url(#hr-fill)"/><path class="tr-hr-line" d="${trace}"/></g></svg><div class="tr-trace-label"><span>Recorded HR · bpm</span><span>${duration(s.sparkline.at(-1).t-s.sparkline[0].t)}</span></div>`:'<p>No heart-rate stream in this source.</p>'}</div><div class="tr-latest-foot"><span>${duration(s.durationS)} <small>${esc(s.durationBasis)} time</small></span><span>${s.paceSPerKm===null?'Pace unavailable':pace(s.paceSPerKm)+' /km'}</span></div>${s.flags.includes('insufficient_distance')?'<p class="tr-quality-note">Distance is too small to calculate a useful pace.</p>':''}</aside>`;
}
function weekChart(){const maximum=Math.max(1000,...data.weeks.map(w=>w.distanceM));return `<div class="tr-week-axis"><span>${km(maximum)} km</span><span>0</span></div><div class="tr-weeks">${data.weeks.map(w=>`<div class="tr-week"><div class="tr-week-track"><div class="tr-week-stack" style="height:${w.distanceM/maximum*100}%"><div class="tr-bar tr-bar-history" style="flex:${w.historicalM}"></div><div class="tr-bar" style="flex:${w.garminM}"></div></div>${w.sessions?`<span class="tr-week-value">${km(w.distanceM)}</span>`:'<span class="tr-zero" aria-hidden="true"></span>'}</div><span>${date(w.start)}</span><span class="sr-only">: ${km(w.distanceM)} kilometres, ${w.sessions} imported sessions</span></div>`).join('')}</div>`;}
function paceChart(){const sessions=data.sessions.filter(s=>s.run&&s.paceSPerKm!==null).toReversed();if(!sessions.length)return '<div class="tr-chart-empty">No run in this window has usable pace. Open an imported session for its recorded time and any available sensor readings.</div>';
 const values=sessions.map(s=>s.paceSPerKm),min=Math.floor((Math.min(...values)-30)/60)*60,max=Math.ceil((Math.max(...values)+30)/60)*60,dates=sessions.map(s=>Date.parse(s.date)),start=Math.min(...dates),end=Math.max(...dates),x=s=>60+(Date.parse(s.date)-start)/(end-start||1)*540,y=s=>24+(s.paceSPerKm-min)/(max-min||1)*150;
 return `<svg class="tr-pace-chart" viewBox="0 0 660 215" role="group" aria-label="Recorded run pace, with faster pace higher on the chart. Values and time bases are listed in the sessions below.">${[min,(min+max)/2,max].map(n=>{const y=24+(n-min)/(max-min||1)*150;return `<path class="tr-grid" d="M58 ${y}H630"/><text x="4" y="${y+4}">${pace(n)}</text>`;}).join('')}${sessions.map(s=>`<a href="${detail(s)}" aria-label="${esc(s.title)}, ${date(s.date,true)}, ${pace(s.paceSPerKm)} per kilometre, ${esc(s.paceBasis)} basis"><circle class="tr-dot-hit" cx="${x(s)}" cy="${y(s)}" r="22"/><circle class="tr-dot ${s.sourceKind==='screenshot'?'is-history':''}" cx="${x(s)}" cy="${y(s)}" r="6"/><title>${esc(s.title)} · ${pace(s.paceSPerKm)} /km · ${esc(s.paceBasis)} basis</title></a>`).join('')}<text x="58" y="210">${date(sessions[0].date)}</text><text x="630" y="210" text-anchor="end">${date(sessions.at(-1).date)}</text></svg><p class="tr-chart-caption">Each dot is one recorded run. Time bases and conditions vary; no fitness trend is inferred.</p>`;
}
function activityRows(){const sessions=data.sessions.filter(s=>type==='all'||(type==='run'?s.run:!s.run));return sessions.length?sessions.map(s=>`<a class="tr-activity" href="${detail(s)}"><div class="tr-activity-date"><strong>${new Date(s.date+'T12:00:00Z').getUTCDate()}</strong><span>${new Date(s.date+'T12:00:00Z').toLocaleDateString('en-AU',{month:'short',year:'2-digit'})}</span></div><div class="tr-activity-name"><h3>${esc(s.title)}</h3><p>${esc(s.source)} · ${s.sourceKind==='screenshot'?'Screenshot import':s.environment==='indoor'?'Indoor':s.gpsSamples?'GPS recorded':'No GPS'}</p></div><div class="tr-row-metric"><strong>${sessionDistance(s.distanceM)}</strong><span>Distance</span></div><div class="tr-row-metric"><strong>${duration(s.durationS)}</strong><span>${esc(s.durationBasis)} time</span></div><div class="tr-row-metric tr-row-pace"><strong>${pace(s.paceSPerKm)}${s.paceSPerKm===null?'':' <small>/km</small>'}</strong><span>${s.paceSPerKm===null?'Pace unavailable':esc(s.paceBasis)+' pace'}</span></div><span class="tr-row-arrow">${arrow}</span></a>`).join(''):'<p class="tr-empty">No imported sessions match this filter. <a href="/account">Bring in your recordings ↗</a></p>';}
function render(){revealObserver?.disconnect();animation?.revert();root.innerHTML=`<header class="tr-header"><a class="tr-brand" href="/training" aria-label="My Fitness Analyser training overview">${logo}<span>My Fitness<br><strong>Analyser</strong></span></a><nav aria-label="Main"><a href="#training-main" aria-current="page">Training</a><a href="#progress">Progress</a><a href="/journal">Journal</a><a href="/account">Account</a></nav><button class="tr-motion" id="motion" aria-pressed="${motion&&!reduced.matches}" aria-label="Toggle motion effects">Motion <span>${motion&&!reduced.matches?'on':'off'}</span></button></header><main id="training-main" class="tr-main"><section class="tr-hero"><div class="tr-hero-intro tr-enter"><h1>Your training.<br><em>In focus.</em></h1><p class="tr-hero-copy">${data.dataset==='synthetic'?'Synthetic design preview · no account data':'Your sessions, your progress, your next move.'}</p><div class="tr-shortcuts"><a href="#sessions">Open sessions ${arrow}</a><a href="${data.cloud?'#coaching':'#intelligence'}">${data.cloud?'Your briefing':'Analysis lab'} ${arrow}</a></div><div class="tr-primary-number"><strong>${km(data.metrics.distanceM)}</strong><span>km<br><small>${windowChoice==='90'?'across the last 90 days':'in your imported history'}</small></span></div><div class="tr-hero-metrics"><div><strong>${data.metrics.sessions}</strong><span>sessions</span></div><div><strong>${duration(data.metrics.recordedTimeS)}</strong><span>recorded time · mixed bases</span></div><div><strong>${data.metrics.runs}</strong><span>runs</span></div></div></div>${latestCard()}<div class="tr-toolbar"><div class="tr-window" role="group" aria-label="History window"><button data-window="90" aria-pressed="${windowChoice==='90'}">Last 90 days</button><button data-window="all" aria-pressed="${windowChoice==='all'}">All imported</button></div><div class="tr-sync-group"><span id="sync-status" role="status">${data.local?(data.lastSync?'Garmin synced '+new Date(data.lastSync).toLocaleDateString('en-AU',{day:'numeric',month:'short'}):'Local Garmin library'):data.cloud?'Your private library':'Synthetic preview · no account connected'}</span>${data.local||data.garminConfigured?'<button class="tr-sync" id="sync">Sync Garmin <span aria-hidden="true">↻</span></button>':''}</div></div></section><section class="tr-volume tr-section tr-enter" aria-labelledby="volume-title"><div class="tr-section-head"><div><h2 id="volume-title">Your recorded rhythm.</h2></div><div class="tr-legend"><span><i></i>Garmin / FIT</span><span><i class="history"></i>Historical summary</span></div></div><div class="tr-week-chart" role="group" aria-label="Imported distance by week, last eight weeks">${weekChart()}</div><p class="tr-chart-caption">Weekly distance · weeks beginning Monday. Empty weeks mean no imported sessions.</p></section><section class="tr-inspect tr-section"><div class="tr-pace-panel tr-enter"><div class="tr-section-head"><div><h2>Recorded pace.</h2></div><span class="tr-chart-unit">min/km</span></div>${paceChart()}</div><div class="tr-coverage tr-enter"><h2>Know what’s<br> in the record.</h2>${[['Heart rate',data.metrics.hrSessions,'var(--color-heartRate)'],['GPS streams',data.metrics.gpsSessions,'var(--color-accent)'],['Usable run pace',data.metrics.paceSessions,'var(--color-positive)']].map(([label,n,color])=>`<div class="tr-coverage-row"><div><span>${label}</span><strong>${n}<small> / ${label==='Usable run pace'?data.metrics.runs:data.metrics.sessions}</small></strong></div><div class="tr-coverage-track"><i style="width:${n/(label==='Usable run pace'?data.metrics.runs:data.metrics.sessions||1)*100||0}%;background:${color}"></i></div></div>`).join('')}<p>Coverage of imported sessions. Missing sensor data stays missing.</p></div></section><section class="tr-readings tr-enter" aria-label="Measured observations">${data.measured.map((m,i)=>`<article><h3>${esc(m.title)}</h3><p>${esc(m.body)}</p><span class="tr-measured">Measured from your record · no AI</span></article>`).join('')}</section><section id="sessions" class="tr-section tr-sessions"><div class="tr-section-head"><div><h2>Every effort, intact.</h2></div><div class="tr-window" role="group" aria-label="Session type">${[['all','All'],['run','Running'],['walk','Walking']].map(([key,label])=>`<button data-type="${key}" aria-pressed="${type===key}">${label}</button>`).join('')}</div></div><div id="session-rows">${activityRows()}</div><p class="tr-chart-caption">Source values retained. Open a session for its route, sensor samples and check-in.</p></section><section id="intelligence" class="tr-lab tr-section tr-enter"><div class="tr-lab-intro"><span class="tr-eyebrow">04 / Analysis lab <span class="tr-demo-badge">Synthetic only</span></span><h2>MORE SIGNAL.<br><em>LESS GUESSWORK.</em></h2><p>A separate test space for Gemini. Findings cite supplied evidence. Charts use recorded values. Your Garmin history stays out of these requests.</p><div class="tr-lab-method"><span>Evidence</span><i>→</i><span>Gemini</span><i>→</i><span>Validation</span></div></div><div id="lab-content" class="tr-lab-content" aria-live="polite"><p>Checking the analysis lab…</p></div></section><footer class="tr-footer"><span>MY FITNESS ANALYSER</span><p>${esc(data.scope)}</p><a href="/app.html">Open activity detail ${arrow}</a></footer></main><div class="tr-notice" id="notice" role="status"></div>`;
 const progress=document.createElement('section');progress.id='progress';progress.className='pr-section';progress.setAttribute('aria-label','Training progress');document.querySelector('.tr-hero').after(progress);mountProgress(progress,data);
 if(data.cloud){document.querySelector('#intelligence')?.remove();const link=document.querySelector('a[href="#intelligence"]');if(link){link.href='#coaching';link.textContent='Your briefing';}const coach=document.createElement('section');coach.setAttribute('aria-label','Your coaching briefing');document.querySelector('#progress').after(coach);mountCoaching(coach);}
 renderLab();bind();animate();
}
function factValue(f){if(f.value===null)return 'Unavailable';if(f.unit==='s/km')return pace(f.value)+' /km';if(f.unit==='s')return duration(f.value);if(f.unit==='m')return km(f.value)+' km';if(f.unit==='percent')return fmt.format(f.value)+'%';return fmt.format(f.value)+(f.unit==='bpm'?' bpm':'');}
function evidenceChips(ids){const facts=new Map((lab.evidence?.facts||[]).map(f=>[f.id,f]));return ids.map(id=>{const f=facts.get(id);return f?`<span class="tr-fact"><small>${esc(f.label)}${f.sessionIds.length?' · '+esc(f.sessionIds.join(', ')):''}</small><strong>${esc(factValue(f))}</strong></span>`:'';}).join('');}
function reviewChart(chart){const field={session_distance:'distanceM',pace_history:'paceSPerKm',heart_rate_history:'hrBpm'}[chart.type],facts=new Map(lab.evidence.facts.map(f=>[f.id,f])),values=chart.sessionIds.map(ref=>({ref,fact:facts.get(ref+'.'+field)})),max=Math.max(...values.map(v=>v.fact.value),1);return `<div class="tr-review-chart"><h4>${esc(chart.type.replaceAll('_',' '))} <span>· synthetic</span></h4>${values.map(v=>`<div><span>${esc(v.ref)}</span><i style="width:${v.fact.value/max*60}%"></i><strong>${esc(factValue(v.fact))}</strong></div>`).join('')}</div>`;}
function renderLab(error=''){const el=document.querySelector('#lab-content');if(!el)return;if(lab===undefined){el.innerHTML='<p role="status">Checking the analysis lab…</p>';return;}if(!lab){el.innerHTML='<p>The analysis lab could not load.</p><button class="secondary-button" id="retry-lab">Retry analysis status</button>';document.querySelector('#retry-lab').addEventListener('click',loadLab);return;}
 const item=lab.review;el.innerHTML=`<div class="tr-lab-status"><span class="tr-demo-badge">${lab.configured?'Ready for a synthetic test':'Setup pending'}</span><span>${esc(lab.model)}</span></div>${error?`<p class="tr-error" role="alert">${esc(error)}</p>`:''}${item?`<div class="tr-review"><span class="tr-eyebrow">Validated Gemini response · synthetic history</span><h3>${esc(item.report.summary)}</h3>${item.report.findings.map(f=>`<article class="tr-review-finding"><span class="tr-eyebrow">${f.confidence==='direct_evidence'?'Direct evidence':'Limited evidence'}</span><h4>${esc(f.title)}</h4><p>${esc(f.explanation)}</p><div class="tr-facts">${evidenceChips(f.factIds)}</div></article>`).join('')}${item.report.visualizations.map(reviewChart).join('')}${item.report.nextChecks.map(c=>`<article class="tr-next-check"><h4>${esc(c.question)}</h4><p>${esc(c.reason)}</p><div class="tr-facts">${evidenceChips(c.factIds)}</div></article>`).join('')}<details><summary>Response provenance</summary><p>Generated ${esc(new Date(item.generatedAt).toLocaleString('en-AU'))} · ${esc(item.returnedModel)} · ${item.cached?'saved response':'new response'}</p><code>${esc(item.evidenceHash)}</code><p>Schema and evidence checks passed. This does not guarantee every interpretation is correct.</p></details></div>`:`<h3>Test the intelligence.<br>Keep the evidence visible.</h3><p>${lab.reason?esc(lab.reason):lab.configured?'The test uses ten generated runs. It will make one Gemini request and validate the response before showing it.':'Add GEMINI_API_KEY to the local .env file. The lab will use ten generated runs when you choose to test it.'}</p>`}<button class="primary-button" id="generate-review" ${!lab.configured||busy?'disabled':''}>${busy?'Waiting for Gemini…':item?'Open saved review':'Test synthetic review'} ${busy?'':arrow}</button><p class="tr-lab-foot">${busy?'One request is running. Results appear only after validation.':'No personal activity data is sent. A saved response is reused for the same evidence and model.'}</p>${lab.evidence?`<details class="tr-evidence"><summary>Inspect the synthetic evidence</summary><p>${lab.evidence.sessions.length} generated sessions · no names, locations or notes.</p><div class="tr-facts">${evidenceChips(['history.sessions','history.distanceM','history.comparableSessions'])}</div><pre>${esc(JSON.stringify(lab.evidence,null,2))}</pre></details>`:''}`;
 document.querySelector('#generate-review')?.addEventListener('click',generate);document.querySelector('#retry-lab')?.addEventListener('click',loadLab);
}
async function loadLab(){try{lab=await json('/api/analysis/status');renderLab();}catch{lab=null;renderLab();}}
async function generate(){if(busy||!lab?.configured)return;busy=true;renderLab();try{const review=await json('/api/analysis/demo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataset:'synthetic'})});lab.review=review;busy=false;renderLab();}catch(e){busy=false;renderLab(e.message);}}
async function load(window='90'){const next=await json('/api/training?window='+window);data=next;windowChoice=window;render();}
function highlightNav(){const hash=location.hash||'#training-main';document.querySelectorAll('.tr-header nav a').forEach(a=>{if(a.getAttribute('href')===hash)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}
window.addEventListener('hashchange',highlightNav);
function bind(){highlightNav();document.querySelectorAll('[data-window]').forEach(b=>b.addEventListener('click',async()=>{if(b.getAttribute('aria-pressed')==='true')return;b.disabled=true;try{await load(b.dataset.window);document.querySelector(`[data-window="${windowChoice}"]`)?.focus({preventScroll:true});}catch(e){b.disabled=false;document.querySelector('#notice').textContent=e.message;}}));document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#session-rows').innerHTML=activityRows();}));document.querySelector('#motion').addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('mfa-visual-motion',motion?'on':'off');}catch{}revealObserver?.disconnect();animation?.revert();document.querySelector('#motion').setAttribute('aria-pressed',String(motion&&!reduced.matches));document.querySelector('#motion span').textContent=motion&&!reduced.matches?'on':'off';if(motion&&!reduced.matches)animate();});document.querySelector('#sync')?.addEventListener('click',async()=>{const button=document.querySelector('#sync'),status=document.querySelector('#sync-status');button.disabled=true;button.textContent='Syncing…';status.textContent='Fetching your Garmin activities…';try{const result=await json('/api/garmin/sync',{method:'POST'});await load(windowChoice);document.querySelector('#sync-status').textContent=`Garmin synced · ${result.imported||0} added · ${result.updated||0} updated`;}catch(e){button.disabled=false;button.innerHTML='Sync Garmin <span aria-hidden="true">↻</span>';status.textContent=e.message;}});}
function animate(){if(!motion||reduced.matches||!window.gsap)return;animation=gsap.context(()=>{gsap.from('.tr-hero-intro',{y:10,duration:.35,ease:'power3.out',clearProps:'transform'});});}
reduced.addEventListener('change',()=>{revealObserver?.disconnect();animation?.revert();const button=document.querySelector('#motion');if(button){button.setAttribute('aria-pressed',String(motion&&!reduced.matches));button.querySelector('span').textContent=motion&&!reduced.matches?'on':'off';}});
try{await load();if(!data.cloud)await loadLab();}catch(e){root.innerHTML=`<main class="training-loading"><h1>Your record couldn’t load.</h1><p>${esc(e.message)}</p><button class="primary-button" id="reload">Retry</button><a class="text-button" href="/app.html">Open activity detail</a></main>`;document.querySelector('#reload').addEventListener('click',()=>location.reload());}
